import{_ as e,o as a,c as s,a4 as n}from"./chunks/framework.BUqnS5H7.js";const g=JSON.parse('{"title":"Checkpoint 与脏页刷新","description":"","frontmatter":{"doc_id":"pg-checkpoint","title":"Checkpoint 与脏页刷新"},"headers":[],"relativePath":"postgresql/02-architecture/chapter-04-checkpoint.md","filePath":"postgresql/02-architecture/chapter-04-checkpoint.md"}'),l={name:"postgresql/02-architecture/chapter-04-checkpoint.md"};function i(c,t,r,p,d,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="checkpoint-与脏页刷新" tabindex="-1" data-src-line="2" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Checkpoint 与脏页刷新 <a class="header-anchor" href="#checkpoint-与脏页刷新" aria-label="Permalink to &quot;Checkpoint 与脏页刷新&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><p data-src-line="4" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>核心问题：</strong> PostgreSQL 的脏页（Dirty Page）何时、如何被刷到磁盘？Checkpoint 对写入性能有什么影响？<code>full_page_writes</code> 是做什么的？理解 Checkpoint 机制，是调优写入密集型工作负载的关键。</p></blockquote><h2 id="_1-checkpoint-是什么" tabindex="-1" data-src-line="6" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">1. Checkpoint 是什么 <a class="header-anchor" href="#_1-checkpoint-是什么" aria-label="Permalink to &quot;1. Checkpoint 是什么&quot;">​</a></h2><p data-src-line="8" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>Checkpoint</strong> 是一个时间点，在这个时间点上，PostgreSQL 保证<strong>所有在该时间点之前产生的脏页都已写入磁盘</strong>。完成 Checkpoint 后，崩溃恢复只需从该 Checkpoint 的 LSN 开始重放 WAL，而不需要从更早的位置开始。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间轴:</span></span>
<span class="line"><span>─────────────────────────────────────────────────────►</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  CP1                                    CP2</span></span>
<span class="line"><span>   │                                      │</span></span>
<span class="line"><span>   ▼                                      ▼</span></span>
<span class="line"><span>   ├──── 脏页范围 ─────────────────────────┤</span></span>
<span class="line"><span>   │                                      │</span></span>
<span class="line"><span>   │  这些脏页必须在 CP2 完成前全部刷盘        │</span></span>
<span class="line"><span>   │                                      │</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  如果在 CP2 之后崩溃:</span></span>
<span class="line"><span>  → 恢复从 CP2 的 redo LSN 开始重放 WAL</span></span>
<span class="line"><span>  → CP2 之前的脏页已经落盘，无需重放</span></span></code></pre></div><h3 id="checkpoint-做了什么" tabindex="-1" data-src-line="27" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Checkpoint 做了什么？ <a class="header-anchor" href="#checkpoint-做了什么" aria-label="Permalink to &quot;Checkpoint 做了什么？&quot;">​</a></h3><table tabindex="0"><thead data-src-line="29" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="29" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">步骤</th><th style="text-align:left;">操作</th><th style="text-align:left;">I/O 特征</th></tr></thead><tbody data-src-line="31" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="31" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">1</td><td style="text-align:left;">记录 Checkpoint 开始（WAL）</td><td style="text-align:left;">顺序写</td></tr><tr data-src-line="32" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">2</td><td style="text-align:left;">将所有脏页刷到磁盘</td><td style="text-align:left;"><strong>大量随机写</strong>（最耗时）</td></tr><tr data-src-line="33" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">3</td><td style="text-align:left;">刷 CLOG、Subtrans 等状态文件</td><td style="text-align:left;">顺序写</td></tr><tr data-src-line="34" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">4</td><td style="text-align:left;">更新 <code>pg_control</code> 控制文件</td><td style="text-align:left;">顺序写</td></tr><tr data-src-line="35" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">5</td><td style="text-align:left;">记录 Checkpoint 完成（WAL）</td><td style="text-align:left;">顺序写</td></tr></tbody></table><blockquote data-src-line="37" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><p data-src-line="37" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>性能关键点：</strong> 步骤 2 是 Checkpoint 最耗时的操作。大量脏页同时刷盘会造成 <strong>I/O 写尖峰</strong>，导致正常查询的响应时间急剧上升。这就是为什么需要 Background Writer 和 <code>checkpoint_completion_target</code> 来平滑 I/O。</p></blockquote><h2 id="_2-checkpoint-触发条件" tabindex="-1" data-src-line="39" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">2. Checkpoint 触发条件 <a class="header-anchor" href="#_2-checkpoint-触发条件" aria-label="Permalink to &quot;2. Checkpoint 触发条件&quot;">​</a></h2><p data-src-line="41" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">PostgreSQL 的 Checkpoint 由以下任一条件触发：</p><table tabindex="0"><thead data-src-line="43" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="43" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">触发条件</th><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="45" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="45" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>超时触发</strong></td><td style="text-align:left;"><code>checkpoint_timeout</code></td><td style="text-align:left;">5 min</td><td style="text-align:left;">距离上次 Checkpoint 超过此时间</td></tr><tr data-src-line="46" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>WAL 量触发</strong></td><td style="text-align:left;"><code>max_wal_size</code></td><td style="text-align:left;">1 GB</td><td style="text-align:left;">自上次 Checkpoint 以来产生的 WAL 量超过此值</td></tr><tr data-src-line="47" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>手动触发</strong></td><td style="text-align:left;"><code>CHECKPOINT</code> 命令</td><td style="text-align:left;">—</td><td style="text-align:left;">DBA 手动执行（如 VACUUM 大表后）</td></tr><tr data-src-line="48" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>干净关库</strong></td><td style="text-align:left;"><code>pg_ctl stop -m fast</code></td><td style="text-align:left;">—</td><td style="text-align:left;">关闭前执行一次 Checkpoint</td></tr></tbody></table><h3 id="参数关系图" tabindex="-1" data-src-line="50" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">参数关系图 <a class="header-anchor" href="#参数关系图" aria-label="Permalink to &quot;参数关系图&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>checkpoint_timeout = 5min</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span>   ┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>   │              Checkpoint 间隔             │</span></span>
<span class="line"><span>   │                                         │</span></span>
<span class="line"><span>   │   CP1 ──────────────────────── CP2      │</span></span>
<span class="line"><span>   │   │                           │         │</span></span>
<span class="line"><span>   │   │←── 最长 5 分钟 ──────────→  │        │</span></span>
<span class="line"><span>   │   │                           │         │</span></span>
<span class="line"><span>   │   │←── 除非 WAL 量达到 ──────→  │         │</span></span>
<span class="line"><span>   │   │    max_wal_size (1GB)     │         │</span></span>
<span class="line"><span>   │   │    先触发                  │         │</span></span>
<span class="line"><span>   └─────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>max_wal_size 越大 → Checkpoint 间隔越长 → 写入性能越好</span></span>
<span class="line"><span>                    → 但恢复时间越长 → pg_wal/ 占用越多</span></span></code></pre></div><h3 id="相关参数" tabindex="-1" data-src-line="72" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">相关参数 <a class="header-anchor" href="#相关参数" aria-label="Permalink to &quot;相关参数&quot;">​</a></h3><table tabindex="0"><thead data-src-line="74" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="74" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="76" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="76" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>checkpoint_timeout</code></td><td style="text-align:left;">5min</td><td style="text-align:left;">Checkpoint 最大间隔（建议 5~30min）</td></tr><tr data-src-line="77" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>max_wal_size</code></td><td style="text-align:left;">1GB</td><td style="text-align:left;">触发 Checkpoint 的 WAL 累积量</td></tr><tr data-src-line="78" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>min_wal_size</code></td><td style="text-align:left;">80MB</td><td style="text-align:left;">pg_wal/ 空间回收的下限</td></tr><tr data-src-line="79" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>checkpoint_warning</code></td><td style="text-align:left;">30s</td><td style="text-align:left;">如果 Checkpoint 间隔小于此值，打印警告日志</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看当前 Checkpoint 配置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW checkpoint_timeout;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 5min</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW max_wal_size;             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 1GB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW checkpoint_completion_target; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 0.9</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 监控 Checkpoint 频率</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_stat_bgwriter;</span></span></code></pre></div><h2 id="_3-checkpoint-completion-target-参数" tabindex="-1" data-src-line="91" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">3. checkpoint_completion_target 参数 <a class="header-anchor" href="#_3-checkpoint-completion-target-参数" aria-label="Permalink to &quot;3. checkpoint_completion_target 参数&quot;">​</a></h2><p data-src-line="93" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><code>checkpoint_completion_target</code> 控制 Checkpoint 脏页刷盘的<strong>节奏</strong>，是平滑 I/O 的核心参数。</p><h3 id="工作原理" tabindex="-1" data-src-line="95" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><p data-src-line="97" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Checkpoint 不是一次性把所有脏页刷完，而是在<strong>两次 Checkpoint 之间的时间窗口</strong>内，按照 <code>checkpoint_completion_target</code> 的比例分散刷盘。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>checkpoint_completion_target = 0.9 (默认)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CP1                                              CP2</span></span>
<span class="line"><span> │                                                │</span></span>
<span class="line"><span> ▼                                                ▼</span></span>
<span class="line"><span> ├────────────────────────────────────────────────┤</span></span>
<span class="line"><span> │                                                │</span></span>
<span class="line"><span> │  [=== 均匀刷脏页 =============================&gt;]│</span></span>
<span class="line"><span> │   ↑                                    ↑       │</span></span>
<span class="line"><span> │   开始刷                        完成(90%处)     │</span></span>
<span class="line"><span> │                                                │</span></span>
<span class="line"><span> │   最后 10% 留给 Checkpoint 快速完成             │</span></span></code></pre></div><h3 id="不同取值的影响" tabindex="-1" data-src-line="114" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">不同取值的影响 <a class="header-anchor" href="#不同取值的影响" aria-label="Permalink to &quot;不同取值的影响&quot;">​</a></h3><table tabindex="0"><thead data-src-line="116" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="116" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">值</th><th style="text-align:left;">行为</th><th style="text-align:left;">适合场景</th></tr></thead><tbody data-src-line="118" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="118" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>0.0</strong></td><td style="text-align:left;">Checkpoint 一开始就集中刷完所有脏页</td><td style="text-align:left;">❌ 不推荐，I/O 尖峰严重</td></tr><tr data-src-line="119" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>0.5</strong></td><td style="text-align:left;">在前 50% 的时间内均匀刷完</td><td style="text-align:left;">写入压力中等</td></tr><tr data-src-line="120" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>0.9</strong></td><td style="text-align:left;">在前 90% 的时间内均匀刷完（默认）</td><td style="text-align:left;">大多数场景，I/O 最平滑</td></tr><tr data-src-line="121" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>1.0</strong></td><td style="text-align:left;">几乎到下次 Checkpoint 才刷完</td><td style="text-align:left;">⚠️ 风险高，可能来不及刷完</td></tr></tbody></table><blockquote data-src-line="123" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><p data-src-line="123" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>调优建议：</strong> 保持默认值 <code>0.9</code> 即可。如果 Checkpoint 期间仍有 I/O 尖峰，应优先增大 <code>max_wal_size</code> 来拉长 Checkpoint 间隔，而非调整此参数。</p></blockquote><h2 id="_4-checkpoint-对性能的影响" tabindex="-1" data-src-line="125" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">4. Checkpoint 对性能的影响 <a class="header-anchor" href="#_4-checkpoint-对性能的影响" aria-label="Permalink to &quot;4. Checkpoint 对性能的影响&quot;">​</a></h2><h3 id="写放大效应" tabindex="-1" data-src-line="127" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">写放大效应 <a class="header-anchor" href="#写放大效应" aria-label="Permalink to &quot;写放大效应&quot;">​</a></h3><p data-src-line="129" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Checkpoint 期间的 I/O 问题主要体现在：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常运行时:</span></span>
<span class="line"><span>  写入速率: ─────────────────────── (平稳)</span></span>
<span class="line"><span>               ↑</span></span>
<span class="line"><span>               │ 小批量写入 (Background Writer)</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Checkpoint 期间:</span></span>
<span class="line"><span>  写入速率: ──────╱══════╲───────── (尖峰)</span></span>
<span class="line"><span>                  ↑      ↑</span></span>
<span class="line"><span>                  │      │</span></span>
<span class="line"><span>            Checkpoint  脏页集中</span></span>
<span class="line"><span>            开始刷盘    涌入磁盘</span></span></code></pre></div><h3 id="checkpoint-性能指标监控" tabindex="-1" data-src-line="146" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Checkpoint 性能指标监控 <a class="header-anchor" href="#checkpoint-性能指标监控" aria-label="Permalink to &quot;Checkpoint 性能指标监控&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看 Checkpoint 统计</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    checkpoints_timed,          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 超时触发的次数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    checkpoints_req,            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- WAL 量触发的次数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    checkpoint_write_time,      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 写脏页耗时 (ms)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    checkpoint_sync_time,       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- fsync 耗时 (ms)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    buffers_checkpoint,         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Checkpoint 写出的缓冲区数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    buffers_clean,              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Bg Writer 写出的缓冲区数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    buffers_backend,            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Backend 直接写出的缓冲区数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    buffers_alloc               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 分配的缓冲区总数</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_stat_bgwriter;</span></span></code></pre></div><table tabindex="0"><thead data-src-line="162" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="162" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">指标</th><th style="text-align:left;">健康范围</th><th style="text-align:left;">异常信号</th></tr></thead><tbody data-src-line="164" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="164" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>checkpoints_req / checkpoints_timed</code></td><td style="text-align:left;">&lt; 0.1</td><td style="text-align:left;">频繁被 WAL 量触发 → 增大 <code>max_wal_size</code></td></tr><tr data-src-line="165" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>buffers_backend / buffers_checkpoint</code></td><td style="text-align:left;">&lt; 0.1</td><td style="text-align:left;">Backend 直接写出过多 → 增大 <code>shared_buffers</code> 或 <code>bgwriter</code> 参数</td></tr><tr data-src-line="166" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>checkpoint_write_time</code></td><td style="text-align:left;">与 <code>checkpoint_sync_time</code> 接近</td><td style="text-align:left;">写入时间远大于 sync → 磁盘写入瓶颈</td></tr></tbody></table><h2 id="_5-background-writer-的作用" tabindex="-1" data-src-line="168" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">5. Background Writer 的作用 <a class="header-anchor" href="#_5-background-writer-的作用" aria-label="Permalink to &quot;5. Background Writer 的作用&quot;">​</a></h2><p data-src-line="170" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Background Writer 是 Checkpoint 的&quot;前置助手&quot;，它的职责是在 Checkpoint 之间<strong>提前将部分脏页刷出</strong>，减轻 Checkpoint 时的 I/O 压力。</p><h3 id="bg-writer-vs-checkpointer" tabindex="-1" data-src-line="172" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Bg Writer vs Checkpointer <a class="header-anchor" href="#bg-writer-vs-checkpointer" aria-label="Permalink to &quot;Bg Writer vs Checkpointer&quot;">​</a></h3><table tabindex="0"><thead data-src-line="174" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="174" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Background Writer</th><th style="text-align:left;">Checkpointer</th></tr></thead><tbody data-src-line="176" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="176" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>职责</strong></td><td style="text-align:left;">提前刷出&quot;不活跃&quot;的脏页</td><td style="text-align:left;">保证<strong>所有</strong>脏页在 Checkpoint 点落盘</td></tr><tr data-src-line="177" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>刷出范围</strong></td><td style="text-align:left;">部分脏页（基于 LRU 策略）</td><td style="text-align:left;">所有在 Checkpoint LSN 之前的脏页</td></tr><tr data-src-line="178" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>刷出策略</strong></td><td style="text-align:left;">周期性扫描，优先刷 usage_count 低的页</td><td style="text-align:left;">必须在 Checkpoint 完成前全部刷完</td></tr><tr data-src-line="179" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>关键参数</strong></td><td style="text-align:left;"><code>bgwriter_delay</code>, <code>bgwriter_lru_maxpages</code>, <code>bgwriter_lru_multiplier</code></td><td style="text-align:left;"><code>checkpoint_completion_target</code></td></tr><tr data-src-line="180" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>是否可被跳过</strong></td><td style="text-align:left;">可以，Backend 可能自己刷脏页</td><td style="text-align:left;">不可以，必须完成</td></tr></tbody></table><h3 id="bg-writer-关键参数" tabindex="-1" data-src-line="182" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">Bg Writer 关键参数 <a class="header-anchor" href="#bg-writer-关键参数" aria-label="Permalink to &quot;Bg Writer 关键参数&quot;">​</a></h3><table tabindex="0"><thead data-src-line="184" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="184" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="186" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="186" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>bgwriter_delay</code></td><td style="text-align:left;">200ms</td><td style="text-align:left;">Bg Writer 唤醒间隔</td></tr><tr data-src-line="187" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>bgwriter_lru_maxpages</code></td><td style="text-align:left;">100</td><td style="text-align:left;">每次最多写出的页数（0 = 禁用 Bg Writer）</td></tr><tr data-src-line="188" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><code>bgwriter_lru_multiplier</code></td><td style="text-align:left;">2.0</td><td style="text-align:left;">预判需要多少干净页可复用，值越大写出越多</td></tr></tbody></table><h3 id="三层脏页刷出体系" tabindex="-1" data-src-line="190" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">三层脏页刷出体系 <a class="header-anchor" href="#三层脏页刷出体系" aria-label="Permalink to &quot;三层脏页刷出体系&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    脏页刷出架构                         │</span></span>
<span class="line"><span>│                                                       │</span></span>
<span class="line"><span>│  Layer 1: Background Writer (持续、小批量)              │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  每 200ms 醒来，刷出 usage_count 低的脏页        │  │</span></span>
<span class="line"><span>│  │  目标: 保持足够的干净页供新数据使用               │  │</span></span>
<span class="line"><span>│  └─────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>│                    │                                  │</span></span>
<span class="line"><span>│                    ▼                                  │</span></span>
<span class="line"><span>│  Layer 2: Checkpointer (周期性、全量)                  │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  每 5min 或 WAL 量达标时触发                     │  │</span></span>
<span class="line"><span>│  │  目标: 保证所有脏页落盘，标记恢复点              │  │</span></span>
<span class="line"><span>│  └─────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>│                    │                                  │</span></span>
<span class="line"><span>│                    ▼                                  │</span></span>
<span class="line"><span>│  Layer 3: Backend 直接写出 (兜底)                      │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  当 Shared Buffers 找不到干净页时                │  │</span></span>
<span class="line"><span>│  │  Backend 被迫自己刷出脏页 → 严重影响查询性能      │  │</span></span>
<span class="line"><span>│  │  buffers_backend 指标上升是信号                  │  │</span></span>
<span class="line"><span>│  └─────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>└───────────────────────────────────────────────────────┘</span></span></code></pre></div><blockquote data-src-line="219" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><p data-src-line="219" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>调优方向：</strong> 如果 <code>buffers_backend</code> 占比过高（&gt; 10%），说明 Bg Writer 和 Checkpointer 的刷出速度跟不上写入速度。应增大 <code>bgwriter_lru_maxpages</code> 或 <code>bgwriter_lru_multiplier</code>，让 Bg Writer 更积极地刷脏页。</p></blockquote><h2 id="_6-full-page-writes-参数" tabindex="-1" data-src-line="221" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">6. full_page_writes 参数 <a class="header-anchor" href="#_6-full-page-writes-参数" aria-label="Permalink to &quot;6. full_page_writes 参数&quot;">​</a></h2><h3 id="问题背景-部分页写入-torn-page" tabindex="-1" data-src-line="223" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">问题背景：部分页写入（Torn Page） <a class="header-anchor" href="#问题背景-部分页写入-torn-page" aria-label="Permalink to &quot;问题背景：部分页写入（Torn Page）&quot;">​</a></h3><p data-src-line="225" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">磁盘通常以扇区（512B 或 4KB）为单位写入。如果在写入 8KB 数据页的过程中断电，可能只有前 4KB 被写入，后 4KB 仍是旧数据 — 这就是 <strong>部分页写入（Torn Page）</strong> 问题。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常写入 8KB 数据页:</span></span>
<span class="line"><span>[═══════════════════════════════════]  ✅ 完整写入</span></span>
<span class="line"><span></span></span>
<span class="line"><span>断电导致部分写入:</span></span>
<span class="line"><span>[════════════════░░░░░░░░░░░░░░░░░░]  ❌ 只写了前半部分</span></span>
<span class="line"><span>                   ↑</span></span>
<span class="line"><span>                   断电点</span></span>
<span class="line"><span>                   前半部分 = 新数据</span></span>
<span class="line"><span>                   后半部分 = 旧数据</span></span>
<span class="line"><span>                   → 页面不一致！</span></span></code></pre></div><h3 id="full-page-writes-的解决方案" tabindex="-1" data-src-line="240" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">full_page_writes 的解决方案 <a class="header-anchor" href="#full-page-writes-的解决方案" aria-label="Permalink to &quot;full_page_writes 的解决方案&quot;">​</a></h3><p data-src-line="242" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><code>full_page_writes = on</code>（默认）时，每次 Checkpoint 后<strong>第一次修改</strong>某个数据页，会将该页的<strong>完整内容</strong>写入 WAL 记录（Full Page Image），而非仅记录增量变化。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAL 记录类型:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  普通 WAL 记录: [LSN] [操作类型] [增量数据]  (小)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  Full Page Image: [LSN] [操作类型] [整页 8KB 数据]  (大)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当 full_page_writes = on:</span></span>
<span class="line"><span>  Checkpoint 后首次修改某页 → 写 Full Page Image</span></span>
<span class="line"><span>  后续修改该页           → 写普通 WAL 记录 (增量)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>恢复时:</span></span>
<span class="line"><span>  即使数据页部分写入损坏</span></span>
<span class="line"><span>  → 用 Full Page Image 恢复完整页面</span></span>
<span class="line"><span>  → 再重放后续增量 WAL 记录</span></span>
<span class="line"><span>  → 数据一致性得到保证</span></span></code></pre></div><h3 id="full-page-writes-的性能影响" tabindex="-1" data-src-line="262" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">full_page_writes 的性能影响 <a class="header-anchor" href="#full-page-writes-的性能影响" aria-label="Permalink to &quot;full_page_writes 的性能影响&quot;">​</a></h3><table tabindex="0"><thead data-src-line="264" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="264" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">场景</th><th style="text-align:left;">影响</th></tr></thead><tbody data-src-line="266" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="266" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">Checkpoint 刚完成后的写入</td><td style="text-align:left;">WAL 量显著增大（每页首次修改多 8KB）</td></tr><tr data-src-line="267" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">大批量 UPDATE/INSERT</td><td style="text-align:left;">Checkpoint 后短时间内 WAL 膨胀</td></tr><tr data-src-line="268" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">关闭 full_page_writes</td><td style="text-align:left;">WAL 量减少，但有数据损坏风险</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看设置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW full_page_writes;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 通常不建议关闭！</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 如果底层存储保证原子写入（如某些企业级 SSD、ZFS），可以考虑关闭</span></span></code></pre></div><blockquote data-src-line="278" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><p data-src-line="278" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>⚠️ 不要轻易关闭：</strong> 除非你确定存储层支持原子写入（如 ZFS、部分企业存储阵列），否则关闭 <code>full_page_writes</code> 可能导致数据损坏。在大多数场景下保持默认值 <code>on</code>。</p></blockquote><h2 id="_7-与-mysql-redo-log-checkpoint-对比" tabindex="-1" data-src-line="280" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">7. 与 MySQL Redo Log Checkpoint 对比 <a class="header-anchor" href="#_7-与-mysql-redo-log-checkpoint-对比" aria-label="Permalink to &quot;7. 与 MySQL Redo Log Checkpoint 对比&quot;">​</a></h2><table tabindex="0"><thead data-src-line="282" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="282" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">维度</th><th style="text-align:left;">PostgreSQL</th><th style="text-align:left;">MySQL (InnoDB)</th></tr></thead><tbody data-src-line="284" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="284" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>日志名称</strong></td><td style="text-align:left;">WAL (Write-Ahead Log)</td><td style="text-align:left;">Redo Log (ib_logfile)</td></tr><tr data-src-line="285" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>日志结构</strong></td><td style="text-align:left;">多个 16MB 段文件</td><td style="text-align:left;">固定大小的循环文件组</td></tr><tr data-src-line="286" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>Checkpoint 方式</strong></td><td style="text-align:left;">独立进程 Checkpointer，周期性全量刷脏页</td><td style="text-align:left;">模糊检查点（Fuzzy Checkpoint），持续部分刷脏页</td></tr><tr data-src-line="287" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>刷脏页时机</strong></td><td style="text-align:left;">Bg Writer 持续预刷 + Checkpointer 全量刷</td><td style="text-align:left;">Master Thread、Page Cleaner 线程</td></tr><tr data-src-line="288" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>Checkpoint 标记</strong></td><td style="text-align:left;">WAL 中的 Checkpoint 记录 + pg_control</td><td style="text-align:left;">Redo Log 中的 checkpoint LSN</td></tr><tr data-src-line="289" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>日志空间管理</strong></td><td style="text-align:left;">段文件循环覆盖（归档后可删除）</td><td style="text-align:left;">固定大小循环写入</td></tr><tr data-src-line="290" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>full_page_writes</strong></td><td style="text-align:left;">默认开启，Checkpoint 后首次修改写全页</td><td style="text-align:left;">通过 Doublewrite Buffer 解决部分页写入</td></tr><tr data-src-line="291" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>I/O 平滑策略</strong></td><td style="text-align:left;">checkpoint_completion_target (0.9)</td><td style="text-align:left;">自适应刷脏（innodb_adaptive_flushing）</td></tr><tr data-src-line="292" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>脏页比例监控</strong></td><td style="text-align:left;">pg_stat_bgwriter</td><td style="text-align:left;">innodb_max_dirty_pages_pct</td></tr><tr data-src-line="293" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;"><strong>恢复速度</strong></td><td style="text-align:left;">取决于 Checkpoint 间隔 × WAL 重放速率</td><td style="text-align:left;">取决于 Redo Log 量 × 重放速率</td></tr></tbody></table><h3 id="架构差异图" tabindex="-1" data-src-line="295" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">架构差异图 <a class="header-anchor" href="#架构差异图" aria-label="Permalink to &quot;架构差异图&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PostgreSQL Checkpoint 模型:</span></span>
<span class="line"><span>┌────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  CP1 ───── Bg Writer 预刷 ────── CP2       │</span></span>
<span class="line"><span>│   │                             │          │</span></span>
<span class="line"><span>│   │←── checkpoint_target=0.9 ──→│          │</span></span>
<span class="line"><span>│   │   (均匀分散刷脏)             │          │</span></span>
<span class="line"><span>│   │                             │          │</span></span>
<span class="line"><span>│   └── Checkpointer 全量刷完 ────┘          │</span></span>
<span class="line"><span>└────────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MySQL InnoDB Checkpoint 模型:</span></span>
<span class="line"><span>┌────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Redo Log 循环写入                           │</span></span>
<span class="line"><span>│   │                                        │</span></span>
<span class="line"><span>│   ├── checkpoint_age → 接近 log 容量时      │</span></span>
<span class="line"><span>│   │   触发激进刷脏                          │</span></span>
<span class="line"><span>│   │                                        │</span></span>
<span class="line"><span>│   ├── innodb_adaptive_flushing             │</span></span>
<span class="line"><span>│   │   根据 redo 产生速率动态调整刷脏速度     │</span></span>
<span class="line"><span>│   │                                        │</span></span>
<span class="line"><span>│   └── Page Cleaner 线程                    │</span></span>
<span class="line"><span>│       (多线程并行刷脏)                      │</span></span>
<span class="line"><span>└────────────────────────────────────────────┘</span></span></code></pre></div><blockquote data-src-line="323" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><p data-src-line="323" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><strong>关键区别总结：</strong> PG 的 Checkpoint 是<strong>周期性全量</strong>的，通过 <code>checkpoint_completion_target</code> 平滑 I/O；MySQL 是<strong>持续增量</strong>的，通过自适应刷脏算法动态调整。PG 的方式更简单可控，MySQL 的方式理论上 I/O 更平滑，但调优更复杂。</p></blockquote><h2 id="本章小结" tabindex="-1" data-src-line="325" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><table tabindex="0"><thead data-src-line="327" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="327" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><th style="text-align:left;">要点</th><th style="text-align:left;">记忆关键词</th></tr></thead><tbody data-src-line="329" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><tr data-src-line="329" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">Checkpoint 将所有脏页刷盘</td><td style="text-align:left;">标记恢复点，缩短恢复时间</td></tr><tr data-src-line="330" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">两种触发：超时(5min) + WAL 量(1GB)</td><td style="text-align:left;"><code>max_wal_size</code> 是核心调优参数</td></tr><tr data-src-line="331" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">checkpoint_completion_target = 0.9</td><td style="text-align:left;">分散刷脏，平滑 I/O</td></tr><tr data-src-line="332" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">Background Writer 提前预刷脏页</td><td style="text-align:left;">三层体系：Bg Writer → Checkpointer → Backend</td></tr><tr data-src-line="333" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">full_page_writes 防止部分页写入</td><td style="text-align:left;">Checkpoint 后首次修改写全页，不要关闭</td></tr><tr data-src-line="334" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">buffers_backend 过高说明刷脏不及时</td><td style="text-align:left;">增大 Bg Writer 参数或 shared_buffers</td></tr><tr data-src-line="335" data-src-file="postgresql/02-architecture/chapter-04-checkpoint.md"><td style="text-align:left;">PG 是周期性全量 Checkpoint</td><td style="text-align:left;">MySQL 是持续增量，理念不同</td></tr></tbody></table>`,58)])])}const k=e(l,[["render",i]]);export{g as __pageData,k as default};
